// Fast path: consistent hidden class
function createPoint(x, y) {
  return { x, y }; // Hidden class: Point{x, y}
}

const p1 = createPoint(10, 20);
const p2 = createPoint(30, 40);
// p1 and p2 share the same hidden class → fast property access

// Slow path: hidden class transitions
function createMutablePoint(x, y, z) {
  const point = { x, y }; // Hidden class: Point{x, y}
  point.z = z;            // Transition to Point{x, y, z}
  return point;
}

const p3 = createMutablePoint(10, 20, 30);
const p4 = createMutablePoint(1, 2, 3);
// p3 and p4 transition at different times → different hidden classes
// Engine can no longer optimize property access reliably

// Best practice: initialize all properties upfront
function createUser(name, email) {
  return {
    name,
    email,
    age: null,
    address: null
  };
}
// Single hidden class for all user objects → maximum optimization

// Monomorphic: single type observed
function add(a, b) {
  return a + b;
}
add(1, 2);
add(3, 4);
// Engine creates one optimized version → fast

// Polymorphic: a few types observed
function addPoly(a, b) {
  return a + b;
}
addPoly(1, 2);
addPoly('a', 'b');
// Engine creates a few optimized versions → still decent

