// Application in React:
// Props that are always the same shape help React's own optimizations
function Card({ title, body, footer }) {
  return (
    <article>
      <h2>{title}</h2>
      <p>{body}</p>
      {footer}
    </article>
  );
}
// Consistent prop shape → stable hidden classes for props object

// ANTI-PATTERN 1: Modifying object shape after creation
const config = {};
config.url = '/api';
config.method = 'GET';
config.timeout = 5000;
// Each property addition changes the hidden class

// FIX: Initialize all properties at once
const config = { url: '/api', method: 'GET', timeout: 5000 };

// ANTI-PATTERN 2: Deleting properties
const user = { name: 'Alice', tempFlag: true };
delete user.tempFlag;
// Deleting breaks hidden class optimizations

// FIX: Set to null or undefined instead
user.tempFlag = null;

// ANTI-PATTERN 3: arguments object
function sum() {
  let total = 0;
  for (let i = 0; i < arguments.length; i++) {
    total += arguments[i];
  }
  return total;
}

// FIX: Use rest parameters
function sum(...numbers) {
  return numbers.reduce((a, b) => a + b, 0);
}

// ANTI-PATTERN 4: Heterogeneous arrays
const mixed = [1, 'two', true, { four: 4 }];
// Engine cannot optimize array operations

// FIX: Separate arrays by type or use typed arrays
const numbers = [1, 2, 3, 4];
const strings = ['one', 'two', 'three', 'four'];

// Bad: inline object creates new hidden class every render
<UserCard user={{ name: 'Alice', age: 30 }} />

// Good: stable reference
const user = useMemo(() => ({ name: 'Alice', age: 30 }), []);
<UserCard user={user} />

// Bad: inline function creates new hidden class every render
<button onClick={() => handleClick(id)}>Click</button>

// Good: stable callback
const handleClick = useCallback((id) => {
  console.log(id);
}, []);
<button onClick={() => handleClick(id)}>Click</button>

